        &lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#COLERE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Col&#232;re&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#HERESIE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;H&#233;r&#233;sie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#PECHE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;P&#233;ch&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#VENGEANCE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Vengeance&lt;/a&gt;&lt;/td&gt;
